import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
const $=s=>document.querySelector(s),palette=['#7bcac8','#89a9ed','#d7ae7c'];
const state={phase:0,event:0,ship:1,candidate:0,selected:null,measure:false,pair:[],playing:false,pulse:0};
let data,renderer,scene,camera,controls,world,routeGroup,measureGroup,meshes=[],labels=[],halos=[],timer;
const n=(x,d=1)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const planetName=i=>data.planets[i].name;
const route=()=>data.routes[state.ship];
const event=()=>data.clustering.events[state.event];
const position=i=>i===-1?data.station.position:data.planets[i].position;
const vector=i=>new THREE.Vector3(...position(i)).subScalar(50);
const distance=(a,b)=>Math.hypot(...position(a).map((v,i)=>v-position(b)[i]));
function chronological(a,complete=false){const stages=a.stages||[];const g=stages.filter(s=>s.accepted).map(s=>s.selected);if(complete&&a.feasible){const used=new Set(g.flat());g.push(data.planets.map(p=>p.id).filter(i=>!used.has(i)))}return g}
function groups(){if(state.phase===0)return [];if(state.phase>=2)return data.routes.map(r=>r.group);const e=event(),a=data.clustering.attempts[e.attempt];if(e.type==='complete')return chronological(a,true);return a.stages.filter(s=>s.vehicle<=e.vehicle&&s.accepted).map(s=>s.selected)}
function currentCandidate(){return route().candidates[state.candidate]}
function stop(){clearInterval(timer);state.playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play process')}
function phase(p){stop();state.phase=p;state.selected=null;if(p===1)state.event=0;if(p===2){state.ship=Math.max(0,data.routes.findIndex(r=>r.atoms));state.candidate=0}render()}
function next(){if(state.phase===0){phase(1);return}if(state.phase===1){if(state.event<data.clustering.events.length-1)state.event++;else{phase(2);return}}else if(state.phase===2){if(state.candidate<route().candidates.length-1)state.candidate++;else{phase(3);return}}else return;render()}
function play(){if(state.playing){stop();return}if(state.phase===0||state.phase===3)phase(1);if(state.phase===1&&state.event===data.clustering.events.length-1)state.event=0;if(state.phase===2&&state.candidate===route().candidates.length-1)state.candidate=0;state.playing=true;$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause process');timer=setInterval(()=>{if(state.phase===1&&state.event<data.clustering.events.length-1)state.event++;else if(state.phase===2&&state.candidate<route().candidates.length-1)state.candidate++;else{stop();return}render()},Number($('#speed').value));render()}
function selectPlanet(i){state.selected=i;if(state.measure){if(state.pair.length>=2)state.pair=[];if(!state.pair.includes(i))state.pair.push(i)}render()}
function texture(index){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=256;const c=canvas.getContext('2d');const colors=['#5d8295','#b28866','#758786','#a29a7a','#8a6d78','#799eae','#998375','#6f839b','#8e9384','#827897'];c.fillStyle=colors[index];c.fillRect(0,0,512,256);for(let j=0;j<80;j++){const y=j/80*256;c.fillStyle=`rgba(${index%2?230:30},${index%2?210:50},${index%2?170:65},${.025+Math.sin(j*4.1+index)*.02})`;c.fillRect(0,y,512,2+Math.abs(Math.sin(j*3))*6)}for(let j=0;j<25;j++){const x=(Math.sin(j*127.1+index)*43758.54%1+1)%1*512,y=(Math.sin(j*19.7+index)*4531.1%1+1)%1*256;c.fillStyle='rgba(25,35,48,.05)';c.beginPath();c.ellipse(x,y,8+j%6,3+j%4,0,0,Math.PI*2);c.fill()}const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;return t}
function init3D(){const host=$('#scene');try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor('#0b1320');renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;host.prepend(renderer.domElement)}catch(e){$('#scene-error').hidden=false;$('#scene-error').textContent='This 3D view requires WebGL. Enable hardware acceleration or use a WebGL-capable browser.';throw e}
 scene=new THREE.Scene();scene.fog=new THREE.FogExp2('#0b1320',.0016);camera=new THREE.PerspectiveCamera(40,1,.1,1000);camera.position.set(110,80,-100);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.07;controls.enablePan=false;controls.minDistance=100;controls.maxDistance=330;controls.target.set(0,0,0);
 scene.add(new THREE.AmbientLight('#a4bce6',.8));const key=new THREE.DirectionalLight('#e5f4ff',3.1);key.position.set(-65,80,65);scene.add(key);const rim=new THREE.DirectionalLight('#5e8ada',1);rim.position.set(70,-10,-70);scene.add(rim);
 const vertices=[];for(let i=0;i<600;i++){const a=i*2.39996,z=1-2*(i+.5)/600,r=Math.sqrt(1-z*z),radius=210+(i%7)*13;vertices.push(Math.cos(a)*r*radius,z*radius,Math.sin(a)*r*radius)}const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:'#8198b8',size:.36,transparent:true,opacity:.46,sizeAttenuation:true})));
 const grid=new THREE.GridHelper(120,12,'#263e56','#182b40');grid.position.y=-50;grid.material.transparent=true;grid.material.opacity=.27;scene.add(grid);world=new THREE.Group();scene.add(world);routeGroup=new THREE.Group();measureGroup=new THREE.Group();scene.add(routeGroup,measureGroup);
 data.planets.forEach((p,i)=>{const radius=2.4+(i%3)*.32;const body=new THREE.Mesh(new THREE.SphereGeometry(radius,40,28),new THREE.MeshStandardMaterial({map:texture(i),roughness:.9,metalness:.04}));body.position.copy(vector(i));body.userData.planet=i;world.add(body);meshes.push(body);const halo=new THREE.Mesh(new THREE.SphereGeometry(radius*1.23,28,20),new THREE.MeshBasicMaterial({color:'#7bcac8',transparent:true,opacity:.045,depthWrite:false,side:THREE.BackSide}));halo.position.copy(body.position);world.add(halo);halos.push(halo);
 if(i===4||i===8){const ring=new THREE.Mesh(new THREE.RingGeometry(radius*1.42,radius*1.85,64),new THREE.MeshStandardMaterial({color:i===4?'#ae9299':'#9ea792',side:THREE.DoubleSide,transparent:true,opacity:.3,roughness:1}));ring.rotation.x=Math.PI*.39;ring.rotation.y=.35;body.add(ring)}
 const label=document.createElement('button');label.className='planet-label';label.setAttribute('aria-label',`${p.name}: (${p.position.join(', ')}), demand 5 units`);label.onclick=()=>selectPlanet(i);$('#planet-labels').append(label);labels.push(label)});
 const station=new THREE.Mesh(new THREE.OctahedronGeometry(2.3),new THREE.MeshStandardMaterial({color:'#d1e6ed',emissive:'#679aa4',emissiveIntensity:.45,roughness:.45}));station.position.copy(vector(-1));world.add(station);const stationRing=new THREE.Mesh(new THREE.TorusGeometry(4.2,.08,8,70),new THREE.MeshBasicMaterial({color:'#82afb8',transparent:true,opacity:.4}));stationRing.rotation.x=Math.PI/2;stationRing.position.copy(vector(-1));world.add(stationRing);const stationLabel=document.createElement('button');stationLabel.className='planet-label station';stationLabel.textContent='◇ Origin Station';stationLabel.onclick=()=>{state.selected=-1;render()};$('#planet-labels').append(stationLabel);labels.push(stationLabel);
 const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down=[0,0];renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const b=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(meshes,false)[0];if(hit)selectPlanet(hit.object.userData.planet)});
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(host);resize();
 function animate(){requestAnimationFrame(animate);controls.update();const width=host.clientWidth,height=host.clientHeight;[...data.planets.map((_,i)=>i),-1].forEach((id,k)=>{const v=vector(id);v.y-=id===-1?4:4.5;v.project(camera);const label=labels[k];label.style.left=(v.x*.5+.5)*width+'px';label.style.top=(-v.y*.5+.5)*height+'px';label.style.display=v.z>1||v.z<-1?'none':'block'});renderer.render(scene,camera)}animate()}
function clear(group){while(group.children.length){const obj=group.children[0];group.remove(obj);obj.traverse(x=>{x.geometry?.dispose();if(x.material){if(Array.isArray(x.material))x.material.forEach(m=>m.dispose());else x.material.dispose()}})}}
function segment(a,b,color,radius=.13,opacity=.85,group=routeGroup){const d=b.clone().sub(a),len=d.length();if(!len)return;const tube=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,len,7),new THREE.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false}));tube.position.copy(a).add(b).multiplyScalar(.5);tube.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());group.add(tube)}
function drawRoute(ids,color,opacity=.8){const path=[-1,...ids,-1];for(let i=1;i<path.length;i++)segment(vector(path[i-1]),vector(path[i]),color,.14,opacity)}
function updateScene(){const assignment=new Map();groups().forEach((g,v)=>g.forEach(i=>assignment.set(i,v)));let rejected=[];if(state.phase===1&&event().type==='proposal'&&!event().accepted)rejected=event().selected;
 const selectedRoute=state.phase===2?(currentCandidate()?.route||route().route):state.phase===3?route().route:[];
 data.planets.forEach((p,i)=>{const v=assignment.get(i);const color=rejected.includes(i)?'#d18b8a':v===undefined?'#64798e':palette[v];halos[i].material.color.set(color);halos[i].material.opacity=state.selected===i?.35:v===undefined?.035:state.phase>=2&&v!==state.ship?.1:.28;meshes[i].material.emissive.set(color);meshes[i].material.emissiveIntensity=v===undefined?.025:.12;labels[i].classList.toggle('selected',state.selected===i);labels[i].style.color=v===undefined?'#a4b8d1':color;const order=selectedRoute.indexOf(i);labels[i].innerHTML=(order>=0?`<span class="order" style="--ship:${color}">${order+1}</span>`:'')+esc(p.name)});
 clear(routeGroup);if(state.phase===3){for(const r of data.routes)drawRoute(r.route,palette[r.ship],r.ship===state.ship?.95:.42)}else if(state.phase===2)drawRoute(selectedRoute,palette[state.ship],.9);else if(state.phase===1){groups().forEach((g,v)=>{if(g.length<2)return;const center=new THREE.Vector3();g.forEach(i=>center.add(vector(i)));center.divideScalar(g.length);g.forEach(i=>segment(vector(i),center,palette[v],.07,.35))})}
 clear(measureGroup);if(state.measure&&state.pair.length===2)segment(vector(state.pair[0]),vector(state.pair[1]),'#edf3ff',.18,1,measureGroup);
 $('#measure').setAttribute('aria-pressed',state.measure);let selection='';if(state.measure){selection=state.pair.length===2?`${planetName(state.pair[0])} ↔ ${planetName(state.pair[1])}: ${n(distance(...state.pair),2)} su · √(Δx² + Δy² + Δz²)`:`Select ${state.pair.length?'one more planet':'two planets'} to measure their 3D distance.`}else if(state.selected!==null){const p=state.selected===-1?data.station:data.planets[state.selected];selection=`${p.name} · XYZ (${p.position.join(', ')})${state.selected===-1?' · all routes start and end here':' · demand 5 units'}`}else selection='Drag to rotate the true 3D network. Use Measure to compare any two planets.';$('#selection').textContent=selection;
 const g=groups();$('#ship-legend').innerHTML=data.routes.map(r=>`<button class="ship-chip ${state.ship===r.ship?'active':''}" data-ship="${r.ship}"><i style="background:${palette[r.ship]}"></i>Ship ${r.ship+1}<small>${state.phase?`${g[r.ship]?.length||0} planets`:''}</small></button>`).join('');$('#ship-legend').querySelectorAll('button').forEach(b=>b.onclick=()=>{stop();state.ship=Number(b.dataset.ship);state.candidate=0;state.pulse=0;render()});}
function shipRows(g,bad=null){return g.map((ids,v)=>`<div class="ship-row"><div class="ship-title"><span><i style="background:${palette[v]}"></i>Ship ${v+1}</span><small>${ids.length*5} / 20 cargo</small></div><div class="load-track"><div style="width:${Math.min(100,ids.length/4*100)}%;background:${bad===v?'#d18b8a':palette[v]}"></div></div><div class="planet-list">${ids.map(planetName).join(' · ')||'No planets assigned'}</div></div>`).join('')}
function sequence(ids){return 'Origin <span>→</span> '+ids.map(planetName).join(' <span>→</span> ')+' <span>→</span> Origin'}
function spark(){const values=data.clustering.events.slice(0,state.event+1).filter(e=>e.type==='complete'&&e.best_score!==null).map(e=>e.best_score);if(!values.length)return '';const lo=Math.min(...values)-.1,hi=Math.max(...values)+.1;const d=values.map((v,i)=>(i?'L':'M')+(3+i/Math.max(1,values.length-1)*232)+','+(43-(v-lo)/(hi-lo)*35)).join('');return `<div class="mini-label">BEST CLUSTERING SCORE SO FAR ↓</div><svg class="sparkline" viewBox="0 0 240 48" aria-label="Actual incumbent clustering score"><path d="${d}" fill="none" stroke="#7bcac8" stroke-width="1.8"/></svg>`}
function pulsePanel(r){return `<details class="quantum-details"><summary>Inside the quantum register</summary><p>${r.atoms} atoms encode edges, not planets. Their physical positions are 2D. This is a CPU emulator with DMM control.</p><div class="pulse-numbers"><span id="pulse-time">0.00 μs</span><span id="pulse-prob">Mean excitation: 0.0%</span></div><svg id="pulse-chart" viewBox="0 0 240 55" aria-label="Actual mean Rydberg excitation probability"></svg><input id="pulse-slider" type="range" min="0" max="40" value="${state.pulse}" aria-label="Recorded quantum evolution time"><p>Excitation is a probability, not a definite route before measurement. Coupling-fit error: ${n(r.embedding_error*100)}%.</p></details>`}
function renderPulse(){const r=route(),frames=r.occupations;if(!frames?.length||!$('#pulse-chart'))return;const values=frames.map(f=>f.occupations.reduce((a,b)=>a+b,0)/f.occupations.length),f=frames[state.pulse];const d=values.map((v,i)=>(i?'L':'M')+(i/(values.length-1)*236+2)+','+(51-v*45)).join('');$('#pulse-chart').innerHTML=`<path d="${d}" fill="none" stroke="#89a9ed" stroke-width="1.4"/><line x1="${2+state.pulse/(frames.length-1)*236}" x2="${2+state.pulse/(frames.length-1)*236}" y1="3" y2="53" stroke="#566f91" stroke-dasharray="2 3"/>`;$('#pulse-time').textContent=n(f.time_ns/1000,2)+' μs';$('#pulse-prob').textContent='Mean excitation: '+n(values[state.pulse]*100)+'%';$('#pulse-slider').oninput=e=>{state.pulse=Number(e.target.value);renderPulse()}}
function process(){const box=$('#process-content'),advance=$('#advance');$('#chapter').textContent=['01 / THE INPUT','02 / CLUSTER SELECTION','03 / THE TSP','04 / THE RESULT'][state.phase];$('#process-title').textContent=['Start with the planets.','Who goes on each ship?','Which stop comes next?','One complete delivery plan.'][state.phase];
 if(state.phase===0){$('#explain').textContent='Every planet needs 5 cargo units. Each ship can carry 20, so it can visit at most 4 planets.';box.innerHTML=`<div class="stat-line"><span>Planets / ships</span><strong>10 / 3</strong></div><div class="stat-line"><span>Total demand</span><strong>50 cargo units</strong></div><div class="stat-line"><span>Total fleet capacity</span><strong>60 cargo units</strong></div><p class="note">The goal: serve every planet exactly once and return to Origin Station, with the shortest total travel.</p><p class="note">These are <strong>fictional fixed XYZ positions</strong>. Planet sizes are decorative. Distance uses space units (su).</p>`;advance.innerHTML='Next: assign ships <span>→</span>';advance.onclick=()=>phase(1);return}
 if(state.phase===1){const e=event(),a=data.clustering.attempts[e.attempt];let g=groups();if(e.type==='proposal'){$('#explain').textContent=`The emulator proposed ${e.selected.length} planets for ship ${e.vehicle+1}. Check this choice before moving to the next ship.`;if(!e.accepted){g=[...g];g[e.vehicle]=e.selected}box.innerHTML=shipRows(g,e.accepted?null:e.vehicle)+`<div class="status ${e.accepted?'':'bad'}">${e.accepted?'Accepted':'Rejected'} · ${e.selected_load} / 20 cargo<br>${e.accepted?'The chosen load and remaining fleet capacity pass.':esc(e.reason)+'. This attempt stops here.'}</div><p class="note">Bit 1 selects a planet; bit 0 leaves it for a later ship. This is a proposal, not a guaranteed answer.</p>`+spark()}
 else{$('#explain').textContent=e.feasible?'Every planet is assigned and all ships fit. Now compare this grouping with earlier feasible attempts.':'This attempt did not produce a complete legal assignment. It counts as a failure.';box.innerHTML=shipRows(g)+(e.feasible?`<div class="mini-label">THIS GROUPING'S SCORE</div><div class="score">${n(e.score,3)}<small>dimensionless</small></div><p class="note">Lower rewards compact, balanced groups. <strong>It is not tour distance.</strong></p>`:'')+`<div class="status ${e.feasible?'':'bad'}">${e.feasible?(e.improved?'New best grouping so far.':'Legal, but not better than the incumbent.'):'No repair or certificate fallback.'}</div>`+spark()}
 advance.innerHTML='Show best grouping & route it <span>→</span>';advance.onclick=()=>{state.event=data.clustering.events.findIndex(x=>x.type==='complete'&&x.attempt===data.clustering.best.attempt);phase(2)};return}
 if(state.phase===2){const r=route();const chooser=`<select id="ship-select" class="ship-select" aria-label="Ship route to inspect">${data.routes.map(x=>`<option value="${x.ship}" ${x.ship===state.ship?'selected':''}>Ship ${x.ship+1} · ${x.group.length} planets</option>`).join('')}</select>`;
 if(r.atoms){const c=currentCandidate();$('#explain').textContent=`The emulator measured ${r.shots} bitstrings. ${r.valid_shots} were legal tours. Compare the ${r.candidates.length} distinct legal patterns below.`;box.innerHTML=chooser+`<div class="mini-label">VALID TOUR ${state.candidate+1} / ${r.candidates.length}</div><div class="route-sequence">${sequence(c.route)}</div><div class="score">${n(c.length)}<small>su · this tour</small></div><div class="stat-line"><span>Best scanned so far</span><strong>${n(c.best_so_far)} su</strong></div><div class="stat-line"><span>Measured occurrences</span><strong>${c.count} / ${r.shots} shots</strong></div><div class="candidate-badge ${c.improved?'':'muted'}">${c.improved?'↓ Keep this shorter tour.':'Keep the earlier, shorter tour.'}</div><p class="note">This is the decoder's valid-pattern scan order, not chronological hardware shots.</p>`+pulsePanel(r)}
 else{$('#explain').textContent='This group has only three planets. It is a trivial cluster under the challenge rules, so its tour is solved classically.';box.innerHTML=chooser+`<div class="route-sequence">${sequence(r.route)}</div><div class="score">${n(r.length)}<small>su</small></div><div class="status">Classical / trivial · no quantum routing claim</div>`}
 advance.innerHTML='Next: combine all ship routes <span>→</span>';advance.onclick=()=>phase(3);$('#ship-select').onchange=e=>{stop();state.ship=Number(e.target.value);state.candidate=0;state.pulse=0;render()};renderPulse();return}
 $('#explain').textContent='All planets are served once. The measured quantum tour and the two classical trivial tours are merged and validated.';box.innerHTML=shipRows(data.routes.map(r=>r.group))+`<div class="stat-line"><span>Exact full-problem reference</span><strong>${n(data.reference.cvrp_optimum)} su</strong></div><div class="stat-line"><span>Quantum-routed groups</span><strong>${data.routes.filter(r=>r.atoms).length} / 3</strong></div><div class="stat-line"><span>Classical trivial groups</span><strong>${data.routes.filter(r=>!r.atoms).length} / 3</strong></div><p class="note">This is a legal hybrid plan. A shorter clustering score does not guarantee the shortest final tours.</p>`;advance.innerHTML='Replay from the beginning <span>↺</span>';advance.onclick=()=>phase(0)}
function render(){if(!data||!scene)return;document.querySelectorAll('[data-phase]').forEach(b=>{const active=Number(b.dataset.phase)===state.phase;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#scene-title').textContent=['Ten worlds. One starting station.','A measured proposal becomes a ship assignment.','Numbered planets show this candidate visit order.','Every tour starts and ends at Origin Station.'][state.phase];updateScene();process();
 const e=event();const progress=state.phase===1?state.event:state.phase===2?state.candidate:0;const max=state.phase===1?data.clustering.events.length-1:state.phase===2?Math.max(0,route().candidates.length-1):1;$('#timeline').max=max;$('#timeline').value=progress;$('#timeline').disabled=state.phase===0||state.phase===3||state.phase===2&&!route().atoms;$('#play').disabled=state.phase===2&&!route().atoms;$('#next').disabled=state.phase===3;
 $('#play-label').textContent=state.phase===1?`Attempt ${e.attempt+1} / 64 · ${e.type==='proposal'?'ship '+(e.vehicle+1)+' decision':'assignment result'}`:state.phase===2?route().atoms?`Ship ${state.ship+1} · valid pattern ${state.candidate+1} / ${route().candidates.length}`:'Classical trivial route':state.phase===3?'All routes validated':'Explore the input';$('#play-description').textContent=state.phase===1?'Actual recorded subset proposals and capacity checks.':state.phase===2?'Compare actual decoded tours, not an invented animation.':state.phase===3?'Click a ship to highlight its route.':'The XYZ coordinates stay fixed; only your camera moves.';$('#position').textContent=state.phase===1||state.phase===2?`${progress+1} / ${max+1}`:'—';
 let completed=state.phase===0?0:state.phase===1?e.attempt+(e.type==='complete'?1:0):64;const valid=data.clustering.attempts.slice(0,completed).filter(a=>a.feasible).length;$('#valid-value').innerHTML=completed?`${valid}<small>/ ${completed}</small>`:'—';$('#distance-value').innerHTML=state.phase===3?`${n(data.total_distance)}<small>su</small>`:'—';$('#gap-value').innerHTML=state.phase===3?`${n(data.gap_percent,2)}<small>%</small>`:'—'}
const explanations={valid:'Valid clusterings = complete, capacity-feasible assignments divided by all completed attempts. This run has 40 valid attempts out of 64 (62.5%). Invalid attempts remain in the denominator.',distance:'Final travel distance adds every ship’s route, including departure from and return to Origin Station. All lengths are true XYZ Euclidean distances in fictional space units (su), not physical solar-system distances.',gap:'Gap = (our final distance − exact CVRP optimum) / exact CVRP optimum × 100%. Zero means globally optimal. It is different from clustering-score gap. Here the exact reference is '+ 'computed independently for evaluation, not used to repair the quantum result.'};
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>phase(Number(b.dataset.phase)));document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{const box=$('#definition');if(!box.hidden&&box.dataset.key===b.dataset.help){box.hidden=true;return}box.dataset.key=b.dataset.help;box.textContent=explanations[b.dataset.help];box.hidden=false});$('#measure').onclick=()=>{state.measure=!state.measure;state.pair=[];render()};$('#reset-camera').onclick=()=>{camera.position.set(110,80,-100);controls.target.set(0,0,0);controls.update()};$('#play').onclick=play;$('#next').onclick=()=>{stop();next()};$('#speed').onchange=()=>{if(state.playing){stop();play()}};$('#timeline').oninput=e=>{stop();if(state.phase===1)state.event=Number(e.target.value);else if(state.phase===2)state.candidate=Number(e.target.value);render()};
fetch('data/space.json').then(r=>{if(!r.ok)throw Error('Recorded space experiment is unavailable.');return r.json()}).then(d=>{data=d;state.ship=Math.max(0,data.routes.findIndex(r=>r.atoms));init3D();render();window.orbitReady=true}).catch(e=>{$('#error').hidden=false;$('#error').textContent=e.message;console.error(e)});
